// ─── Stap 1: Telegram bericht uitlezen ───────────────────────────────────
const message = $input.first().json.message;
const text = (message?.text || '').trim();
const chatId = String(message?.chat?.id || '');
const messageId = message?.message_id;
const isVoice = !!message?.voice;

// Voiceberichten worden nog niet verwerkt (vereist Whisper-integratie)
if (isVoice) {
  return [{ json: {
    command: 'voice',
    content: '',
    chatId, messageId, isVoice,
    obsidianContent: '', filepath: '',
    replyText: '🎙️ Spraakberichten worden nog niet ondersteund. Stuur een tekstbericht of gebruik een van de commando\'s (stuur /help voor de lijst).',
    hasPrefix: false
  }}];
}

if (!text) {
  return [{ json: {
    command: 'leeg', content: '', chatId, messageId, isVoice: false,
    obsidianContent: '', filepath: '',
    replyText: 'Leeg bericht ontvangen. Stuur /help voor de beschikbare commando\'s.',
    hasPrefix: false
  }}];
}

// ─── Stap 2: Help-commando detecteren ─────────────────────────────────────
if (text === '/help' || text === '/commando' || text === '/start') {
  return [{ json: {
    command: 'help', content: '', chatId, messageId, isVoice: false,
    obsidianContent: '', filepath: '', replyText: '', hasPrefix: false
  }}];
}

// ─── Stap 3: Commando-prefix detecteren ───────────────────────────────────
const prefixes = [
  ['/notitie', 'notitie'],
  ['/note',    'notitie'],
  ['/taak',    'taak'],
  ['/todo',    'taak'],
  ['/task',    'taak'],
  ['/idee',    'idee'],
  ['/idea',    'idee'],
  ['/dagboek', 'dagboek'],
  ['/journal', 'dagboek'],
];

let command = 'vrij';
let content = text;

for (const [prefix, cmd] of prefixes) {
  if (text.toLowerCase().startsWith(prefix + ' ') || text.toLowerCase() === prefix) {
    command = cmd;
    content = text.slice(prefix.length).trim();
    break;
  }
}

// ─── Stap 4: Tijdstempel ──────────────────────────────────────────────────
const now = new Date();
const pad = n => String(n).padStart(2, '0');
const timestamp = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())} ${pad(now.getHours())}:${pad(now.getMinutes())}`;
const fileTs = `${now.getFullYear()}${pad(now.getMonth()+1)}${pad(now.getDate())}${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;

// ─── Stap 5: Obsidian-inhoud bouwen voor bekende commando's ───────────────
if (command !== 'vrij') {
  const tagMap = { notitie: 'notitie', taak: 'taak', idee: 'idee', dagboek: 'dagboek' };
  const tag = tagMap[command];

  let bodyContent;
  if (command === 'taak') {
    bodyContent = `- [ ] ${content}`;
  } else if (command === 'dagboek') {
    bodyContent = content;
  } else {
    bodyContent = content;
  }

  const obsidianContent = `---\ntags:\n  - ${tag}\n  - telegram\ndatum: ${timestamp}\nbron: telegram\n---\n\n${bodyContent}`;
  const filepath = `/home/node/obsidian-share/inbox/${fileTs}-${command}.md`;

  const labels = {
    notitie: 'Notitie opgeslagen',
    taak: 'Taak toegevoegd ✓',
    idee: 'Idee opgeslagen',
    dagboek: 'Dagboek bijgewerkt'
  };
  const preview = content.length > 60 ? content.substring(0, 60) + '...' : content;
  const replyText = `${labels[command]}: "${preview}"`;

  return [{ json: {
    command, content, chatId, messageId, timestamp, fileTs,
    obsidianContent, filepath, replyText, hasPrefix: true
  }}];
}

// Vrije tekst → door naar LLM
return [{ json: {
  command: 'vrij', content, chatId, messageId, timestamp, fileTs,
  obsidianContent: '', filepath: '', replyText: '', hasPrefix: false
}}];

