// Haal LLM response op
const llmRaw = $input.first().json;

// Ondersteuning voor OpenAI-compatible EN Ollama API-formaat
let responseText = '';
if (llmRaw.choices?.[0]?.message?.content) {
  responseText = llmRaw.choices[0].message.content; // OpenAI-compatible (LM Studio etc.)
} else if (llmRaw.response) {
  responseText = llmRaw.response; // Ollama /api/generate formaat
} else if (llmRaw.message?.content) {
  responseText = llmRaw.message.content; // Ollama /api/chat formaat
} else {
  responseText = JSON.stringify(llmRaw);
}

// Originele context ophalen uit Parse Command
const original = $('Parse Command').first().json;
const { timestamp, fileTs, chatId, messageId, content } = original;

// JSON extraheren uit LLM response
let parsed = null;
try {
  const cleaned = responseText.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  }
} catch(e) {
  parsed = null;
}

// Fallback als JSON-parsing mislukt
const category = parsed?.category || 'notitie';
const title = (parsed?.title || content.substring(0, 50)).replace(/[/\\<>:|?*"]/g, '-');
const formattedContent = parsed?.content || content;
const tags = Array.isArray(parsed?.tags) ? parsed.tags : [category, 'telegram'];

// Obsidian markdown bouwen
const tagsYaml = tags.map(t => `  - ${t}`).join('\n');
const obsidianContent = `---\ntitel: ${title}\ntags:\n${tagsYaml}\ndatum: ${timestamp}\nbron: telegram\ncategorie: ${category}\n---\n\n# ${title}\n\n${formattedContent}`;
const filepath = `/home/node/obsidian-share/inbox/${fileTs}-${category}.md`;

const preview = title.length > 50 ? title.substring(0, 50) + '...' : title;
const replyText = `[${category.toUpperCase()}] Opgeslagen: "<b>${preview}</b>"`;

return [{ json: {
  ...original,
  obsidianContent,
  filepath,
  replyText,
  category,
  title
}}];

// Converteer tekst naar binary zodat Write File het kan wegschrijven
const item = $input.first();
const { obsidianContent, filepath } = item.json;

if (!obsidianContent || !filepath) {
  throw new Error(`Ontbrekende data: obsidianContent=${!!obsidianContent}, filepath=${!!filepath}`);
}

// Zorg dat de directory bestaat (n8n schrijft niet automatisch directories aan)
// filepath voorbeeld: /home/node/obsidian-share/inbox/20240615120000-notitie.md

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(obsidianContent, 'utf8'),
  'note.md',
  'text/markdown'
);

return [{
  json: item.json,
  binary: {
    data: binaryData
  }
}];
